import test from 'node:test';
import assert from 'node:assert/strict';
import {earnOpening} from './opening-flow.mjs';
import {createQuestGuide} from '../quest-navigation.js';
import {campaignObjective,objectiveText} from '../campaign-content.js';
import {assistanceMode,setAssistanceMode,questHint,guidanceDestinations,musicDestinations,validateQuestAssistance} from '../quest-assistance.js';

function musical(chapter=4){const h=earnOpening(),w=h.w;w.state.chapter=chapter;const scenes=w.data.scenes.filter(r=>r.chapter===chapter&&!r.originId&&!r.biome),notes=scenes.flatMap(r=>r.objects.filter(o=>o.type==='note').map(o=>({r,o})));for(const r of scenes)for(const o of r.objects){if(o.type==='npc'&&o.sets_bit!==undefined)w.setBit(o.flag_address??w.data.campaign.missions[chapter-1].flag_address,o.sets_bit);if(o.type==='aid'||o.type==='cache'&&o.bit===5)w.setBit(o.flag_address??w.data.campaign.missions[chapter-1].flag_address,o.bit);}w.state.scene=notes[0].r.location;w.state.x=notes[0].o.xy[0]+.5;w.state.y=notes[0].o.xy[1]+.5;w.state.mode='field';return {...h,w,notes,original:h};}
test('default guidance walks to an instrument but never supplies or plays the next answer',()=>{const h=musical(),w=h.w,guide=createQuestGuide(w,{resolve:()=>campaignObjective(w)});assert.equal(assistanceMode(w.state),'destination');assert.doesNotMatch(objectiveText(w),/Play the low/);guide.start();guide.update(.05);assert.equal(w.state.flags['sequence:'+h.notes[0].o.sequence_address]||0,0);assert.ok(h.original.dialog?.choices);assert.deepEqual(h.original.dialog.choices.slice(0,2).map(x=>x.label),['Sound the low bell','Sound the high bell']);assert.equal(guide.held,true);});
test('choosing a distant sound walks to its real instrument before sounding it, without manual input',()=>{const h=musical(),w=h.w;w.state.flags['sequence:'+h.notes[0].o.sequence_address]=1;const target=musicDestinations(w,h.notes[0].o).find(g=>g.object.note===1),guide=createQuestGuide(w,{resolve:()=>campaignObjective(w)});let moved=0;const move=w.move.bind(w);w.move=(dx,dy)=>{moved++;move(dx,dy);};assert.ok(guide.visit(target));for(let n=0;n<10000&&(w.state.flags['sequence:'+h.notes[0].o.sequence_address]||0)<2;n++){guide.update(.05);h.finish();}assert.ok(moved>0);assert.equal(w.state.scene,target.scene);assert.equal(w.state.flags['sequence:'+h.notes[0].o.sequence_address],2);assert.equal(guide.held,true);});
test('explicit full assistance retains checked traversal through every campaign musical sequence',()=>{for(const chapter of [4,9,13,16,19,21,22,24]){const h=musical(chapter),w=h.w,note=h.notes[0].o,flag=w.data.campaign.missions[chapter-1].flag_address;setAssistanceMode(w.state,'full');const guide=createQuestGuide(w,{resolve:()=>campaignObjective(w)});guide.start();let ticks=0;while(!w.bit(note.flag_address??flag,note.completes_bit)&&ticks++<22000){guide.update(.1);h.finish();assert.equal(!!h.original.dialog?.choices,false,'full musical route must not require an unannounced manual move');}assert.ok(ticks<22000,'chapter '+chapter+' did not complete');guide.cancel();}});
test('hints escalate only on request and never mutate an inventory, answer or story decision',()=>{const h=musical(),w=h.w,before={flags:{...w.state.flags},items:{...w.state.items},choices:{...w.state.storyChoices}},goal=campaignObjective(w);assert.equal(questHint(w,{goal}).stage,0);assert.equal(w.state.questAssistance,undefined);for(let n=1;n<=3;n++)assert.equal(questHint(w,{goal,advance:true}).stage,n);assert.match(questHint(w,{goal}).text,/low/);assert.equal(questHint(w,{goal,advance:true}).stage,3);assert.deepEqual({flags:w.state.flags,items:w.state.items,choices:w.state.storyChoices},before);w.restore(w.save());assert.equal(questHint(w,{goal}).stage,3);});
test('known local clues have one-off walking destinations; hidden unreached caches do not leak through the list',()=>{const h=earnOpening(),w=h.w;w.state.chapter=4;w.loadScene(704);h.finish();const list=guidanceDestinations(w);assert.ok(list.some(d=>d.object.investigationRole==='evidence'));assert.ok(!list.some(d=>d.object.type==='secret'));const goal=list.find(d=>d.object.investigationRole==='evidence'),guide=createQuestGuide(w,{resolve:()=>campaignObjective(w)});guide.visit(goal);for(let n=0;n<4000&&!guide.held;n++){guide.update(.05);h.finish();}assert.equal(guide.held,true);assert.ok(h.dialog?.choices);assert.ok(Math.hypot(w.state.x-goal.object.xy[0]-.5,w.state.y-goal.object.xy[1]-.5)<=2.05);});
test('assistance save validation is bounded and rejects malformed settings without inventing a mode',()=>{validateQuestAssistance({});const s={};assert.equal(setAssistanceMode(s,'autoplay'),false);assert.equal(s.questAssistance,undefined);setAssistanceMode(s,'full');validateQuestAssistance(s);assert.throws(()=>validateQuestAssistance({questAssistance:{version:1,mode:'full',hints:[{key:'x',stage:4}]}}),/assistance/);assert.throws(()=>validateQuestAssistance({questAssistance:{version:1,mode:'full',hints:Array.from({length:65},(_,i)=>({key:String(i),stage:0}))}}),/assistance/);});
